export default function TableRow({tableRowInfo}){
    const rowDetails = [];

    console.log(tableRowInfo);
    console.log(tableRowInfo.rowSize);

    for(let rowIndex = 0; rowIndex < tableRowInfo.rowSize; rowIndex++){
        rowDetails.push(<div className='flex-auto'><textarea className='bg-sky-100 w-4/5'></textarea></div>);
    }

    return (
        <div className='tableRow flex flex-row divide-x divide-black'>
            {rowDetails}
        </div>
    );
}
